
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_hcth_93_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_hcth_93", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.534233483883135e+00, -4.442291459475618e+00, -4.313569082767536e+00, -4.135504470229744e+00, -3.893442392554783e+00, -3.572661129862984e+00, -3.163307720967014e+00, -2.670185017529809e+00, -2.128575120202571e+00, -1.609775641921553e+00, -1.123263603366687e+00, -7.688908405681569e-01, -6.636868272047781e-01, -5.392379149630591e-01, -3.894511517889975e-01, -2.567170733329271e-01, -1.728960047110802e-01, -9.261512582432459e-02, -2.318326255983388e-02, -2.747599425984060e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


